'use strict';
/* Short teaching notes supplement the complete, existing language-specific references. */
window.CONCEPT_LESSONS = (() => {
  const q=(prompt,options,correct,why)=>({prompt,options,correct,why});
  const profiles={};
  function add(id,title,lead,cards,steps,quiz,widget){profiles[id]={title,lead,cards,steps,quiz,widget};}
  add('1-01-objects-constructors-and-immutability','Objects, constructors & immutability',
    'A constructor gives a new object its starting state. Good validation makes that state safe to use.',
    [['Object','One instance with its own state, such as an order’s symbol and quantity.'],['Constructor','Receives values, checks them and stores them in the new object’s fields.'],['Immutability','State cannot change after construction. final fields are one part of that design.']],
    ['Pass the arguments','Validate and assign fields','Receive a usable object'],
    [q('In this.symbol = symbol, what does this.symbol refer to?',['The field on the current object','The constructor parameter','A shared static field'],0,'this identifies the current instance. The unqualified symbol on the right is the parameter.'),q('Does final List<String> tags make the list contents immutable?',['Yes, every element is frozen','No, only the reference cannot be reassigned','Only if the variable is public'],1,'final prevents reassignment of that field. The referenced list can still change unless its structure is protected.'),q('Why validate quantity in the constructor?',['To allow an invalid object temporarily','To prevent an invalid object from being returned','To change the caller’s variable'],1,'A failing constructor throws before the caller receives the newly constructed instance.')],'constructor');
  add('1-02-equality-null-handling-and-object-utility-methods','Equality, nulls & object utilities',
    'First decide whether you are comparing identity, content or a business key. Then handle missing values explicitly.',
    [['Identity','For ordinary objects, == asks whether two references point to the same object.'],['Value equality','equals describes meaningful equality; hashCode must agree for hash-based collections.'],['Missing vs blank','null means no object. isBlank() inspects an existing string.']],
    ['Define what equal means','Guard missing values','Compare using that contract'],
    [q('What is Objects.equals(null, null)?',['true','false','NullPointerException'],0,'Objects.equals handles null references and returns true when both are null.'),q('Why put value == null before value.isBlank() in an || expression?',['It makes the string immutable','Short-circuiting avoids a method call on null','It converts null into an empty string'],1,'When the left side of || is true, Java does not evaluate the right side.'),q('Two objects are equal according to equals. What must hold?',['Their hash codes must match','They must occupy the same memory address','Every object must have a unique hash code'],0,'Equal objects must have the same hash code. Different objects may still have hash collisions.')],'nulls');
  add('1-03-bigdecimal-financial-arithmetic-and-rounding','Exact money & rounding',
    'Keep decimal calculations exact, and choose when and how to round as part of the business contract.',
    [['Construct from text','new BigDecimal("0.1") preserves the decimal value you intended.'],['Arithmetic returns a value','add, multiply and divide return a new BigDecimal; keep the result.'],['Round at the boundary','Sum or multiply first when the contract requires it, then apply an explicit scale and mode.']],
    ['Read exact decimal text','Calculate without early rounding','Apply the agreed rounding rule'],
    [q('What is 3 × 0.335, rounded once to two decimals with HALF_UP?',['1.01','1.02','1.00'],0,'The exact product is 1.005. Rounding the final result gives 1.01. Rounding the price first would produce a different result.'),q('How do 10.0 and 10.00 compare using BigDecimal.compareTo?',['Zero: numerically equal','Positive: the second has more digits','An exception is thrown'],0,'compareTo uses numeric value. equals additionally considers scale.'),q('Does price.multiply(quantity) modify price?',['Yes','No; it returns a new value','Only when quantity is positive'],1,'BigDecimal is immutable. Store or return the new value.')],'money');
  add('1-04-collections-lists-sets-queues-and-copies','Choose the right collection',
    'Choose a collection from the behaviour you need: order, duplicates, membership, queues or a protected snapshot.',
    [['List','Keeps a sequence and permits duplicates. Good when position matters.'],['Set','Keeps distinct members. Iteration order depends on the implementation.'],['Copy vs view','A structural snapshot differs from a view of someone else’s mutable collection.']],
    ['Identify order and duplicate rules','Choose an implementation','Check mutability and copy behaviour'],
    [q('Which set preserves insertion order?',['HashSet','LinkedHashSet','Any Set implementation'],1,'LinkedHashSet preserves encounter order. HashSet does not promise an iteration order.'),q('Can you add a new element to Arrays.asList("A", "B")?',['Yes, it is an ordinary growable ArrayList','No, its size is fixed','Only if the element is unique'],1,'Arrays.asList returns a fixed-size list backed by the array. Replacing an element is different from changing the size.'),q('Is List.copyOf a deep copy of mutable elements?',['Yes','No, it protects the list structure','Only when the list is empty'],1,'The element references are copied. Mutable elements need their own copying policy.')],'collections');
  add('1-05-maps-sorted-maps-and-comparators','Maps, defaults & ordering',
    'A map connects each key to a value. Defaults help with first occurrences; sorted maps add an ordering contract.',
    [['Lookup','getOrDefault supplies a fallback for an absent key.'],['Aggregate','Read a total, add the contribution and store the new value.'],['Order deliberately','TreeMap sorts keys. HashMap does not promise iteration order.']],
    ['Look up the key','Calculate the new value','Write it back to the map'],
    [q('An empty map runs getOrDefault("AAPL", 0). What is returned?',['null','0','An exception'],1,'The key is absent, so the supplied default is returned. This lookup does not insert a mapping.'),q('A HashMap contains X mapped to null. What is getOrDefault("X", 0)?',['0','null','It removes X'],1,'The mapping exists, so its null value is returned. getOrDefault is about key absence, not replacing every null value.'),q('Which map sorts keys by their natural order by default?',['HashMap','LinkedHashMap','TreeMap'],2,'TreeMap maintains sorted keys, using natural order or a supplied comparator.')],'maps');
  add('1-06-streams-pipelines-filtering-mapping-and-ordering','Read a stream pipeline',
    'Read the pipeline as a sequence of questions: which records, which values, and what final result?',
    [['filter','Keeps elements that satisfy a predicate.'],['map','Transforms each retained element into another value.'],['Terminal operation','collect, reduce and other terminal operations produce a result or effect.']],
    ['Select eligible records','Transform the retained values','Collect or reduce a result'],
    [q('Which operation keeps only executed orders?',['map','filter','sorted'],1,'filter selects elements. map changes the value produced for each element.'),q('Which operation is terminal?',['filter','map','collect'],2,'collect consumes the pipeline to produce a result. Intermediate stream operations are lazy.'),q('Can the same Java Stream be consumed twice?',['Yes, it stores a reusable copy','No; create another stream from the source','Only if it is sequential'],1,'A Stream is single-use. The underlying collection may be reusable, but that stream is not.')],'streams');
  add('1-07-collectors-grouping-and-financial-reductions','Group records & reduce totals',
    'A collector describes how to assemble the result: group records, calculate a total, or build a map.',
    [['Group key','Choose what puts records in the same bucket, such as symbol.'],['Downstream collector','Decide what each bucket contains: records, counts or a total.'],['Exact financial totals','Keep decimal precision and round according to the agreed contract.']],
    ['Choose the group key','Choose the per-group result','Collect into the required map'],
    [q('What does groupingBy(Trade::symbol) use as the map key?',['The trade quantity','The symbol','The record’s position'],1,'The classifier computes the key for each record.'),q('Does groupingBy guarantee a sorted result map by default?',['Yes','No; supply a sorted-map factory when needed','Only for string keys'],1,'The default groupingBy collector does not guarantee a particular map type or sorted key order.'),q('For exact monetary totals, when should rounding happen?',['Always before multiplication','At the point required by the domain contract','After converting the total to double'],1,'Rounding policy is part of the calculation contract. Early rounding can change totals.')],'grouping');
  add('1-08-threads-executors-futures-and-lifecycle-management','Tasks, executors & futures',
    'Separate the work you want done from the threads that run it. Then make waiting, failure and cleanup explicit.',
    [['Executor','Owns the workers used to execute submitted tasks.'],['Future','Represents a task’s eventual result or failure. get can wait.'],['Lifecycle','Bound work, choose deadlines and shut down owned executors.']],
    ['Submit independent tasks','Wait for or compose results','Handle failure and close resources'],
    [q('Does ExecutorService.shutdown() wait for every task to finish?',['Yes','No; use appropriate waiting mechanisms','It immediately interrupts every task'],1,'shutdown stops acceptance of new tasks. Waiting for completion is a separate concern.'),q('If futures are read in submission order, must tasks finish in that order?',['Yes','No, completion order can differ','Only with two workers'],1,'You can preserve output order by reading futures in submission order, even when execution completes differently.'),q('What should a task deadline include?',['Only the successful response','The waiting policy and what happens after timeout','Only the number of threads'],1,'Timeout and cancellation need an explicit policy. Timing out while waiting does not automatically make work disappear.')],'executor');
  add('1-09-atomic-updates-concurrent-maps-and-bounded-queues','Make shared updates atomic',
    'Thread-safe storage is useful, but the whole operation you depend on must also be atomic.',
    [['Race','Two workers can read the same old value and overwrite each other’s updates.'],['Atomic update','Use a suitable atomic operation or coordinate the critical section.'],['Bounded capacity','Limit queues and workers so overload has a controlled outcome.']],
    ['Identify the shared state','Define the indivisible operation','Choose coordination and capacity limits'],
    [q('Does a thread-safe map make get(key) followed by put(key, value + 1) atomic?',['Yes','No, the two calls can interleave','Only when the key is a string'],1,'Individual thread-safe calls do not turn a read-modify-write sequence into one atomic action.'),q('What does ConcurrentHashMap.merge help with?',['An atomic update for one key','A transaction over every key','Sorting the map'],0,'The per-key update is atomic. A larger workflow can still require coordination.'),q('Why bound a queue?',['To control overload and resource growth','To make tasks run in a fixed order on every thread','To avoid every possible failure'],0,'A bounded queue requires an explicit overload policy and prevents unlimited queued work.')],'atomic');
  add('1-10-threadlocal-context-and-completablefuture-composition','Context cleanup & async composition',
    'Know which worker owns context, and compose asynchronous results without leaving state behind.',
    [['ThreadLocal','Associates a value with the current thread, not automatically with a request.'],['Cleanup','A reused worker can retain a previous request’s value unless you remove it.'],['Compose futures','thenApply transforms a result; thenCompose chains a future-producing operation.']],
    ['Set or pass the required context','Run the work and compose results','Clean up in finally'],
    [q('Where should owned ThreadLocal context usually be removed?',['In a finally block','Only on a successful request','Only before shutting down the application'],0,'A finally block runs on success and failure, helping prevent context leakage on reused threads.'),q('A function returns CompletableFuture<Result>. Which method flattens the chain?',['thenApply','thenCompose','toString'],1,'thenCompose chains a future-producing function rather than wrapping a future inside another future.'),q('Does ThreadLocal automatically follow work onto another executor thread?',['Yes','No; propagation needs an explicit policy','Only when the value is a string'],1,'Thread-local state belongs to a thread. Asynchronous execution can use another thread.')],'context');

  const general=[
    ['shared-structured-answers','Structure a clear answer','Make your answer easy to follow: give context, explain the decision and support it with evidence.',['Give the context','Explain your contribution','Describe a verifiable result'],q('Which detail makes an experience answer credible?',['A verifiable result and your actual contribution','A longer list of tools','An invented success metric'],0,'Use truthful, specific evidence and make your own responsibilities clear.')],
    ['shared-problem-solving','Clarify, solve & verify','A strong solution starts with a clear contract and ends with evidence that it meets that contract.',['Clarify inputs and rules','Choose an approach','Verify with small and boundary cases'],q('What should you clarify before coding?',['Input, output, ordering and invalid-input behaviour','Only the class name','The interviewer’s preferred editor theme'],0,'A correct implementation depends on the agreed behaviour, including boundaries and failures.')],
    ['core-ledger','Understand ledger movements','A balance tells you the current state. A ledger explains the movements that produced it.',['Define the posting convention','Write related entries atomically','Reconcile and preserve history'],q('In the simplified transfer model, A loses 30 and B gains 30. What is the net movement?',['0','30','60'],0,'The paired signed movements sum to zero. Real debit/credit labels depend on account classification.')],
    ['core-idempotency','Make retries safe','An idempotent operation can be retried without repeating the business effect.',['Choose a stable request identity','Record the accepted outcome','Handle a consistent retry or conflict'],q('An identical payment request is retried with the same idempotency key. What is the goal?',['Apply the payment again','Return the accepted outcome without another business effect','Give every retry a new transaction identity'],1,'The key connects retries to the same accepted operation. Changed payloads require a defined conflict policy.')],
    ['ecommerce-inventory','Reserve stock safely','A stock check and a reservation need a concurrency policy so two buyers cannot both claim the last item.',['Check the reservation contract','Reserve with coordination','Confirm or release the reservation'],q('Two buyers see one available item. Is a separate availability check sufficient?',['Yes','No; the reservation must be coordinated','Only if both use the same browser'],1,'A check followed by a later write can race. Use an atomic reservation or another explicit coordination mechanism.')],
    ['ecommerce-checkout','Model checkout transitions','Treat checkout as a state machine with explicit transitions, retries and recovery.',['Define allowed states','Apply an allowed transition','Handle duplicate or out-of-order events'],q('A payment callback arrives twice. What should the system do?',['Repeat fulfilment twice','Handle the duplicate according to the idempotency contract','Assume callbacks always arrive once'],1,'External events can repeat. State transitions and idempotency protect business effects.')],
    ['ai-evaluation','Evaluate AI with useful evidence','Use representative cases and a clear rubric so a model change can be compared meaningfully.',['Define the task and rubric','Evaluate representative cases','Inspect errors and trade-offs'],q('Why keep a held-out evaluation set?',['To check generalisation beyond tuning examples','To guarantee every future answer is correct','To replace all human review'],0,'Held-out cases help reveal whether improvement extends beyond examples used during iteration.')],
    ['ai-rag','Ground answers in retrieved evidence','Retrieval supplies relevant material; a useful answer still needs to be supported by that material.',['Retrieve relevant context','Generate with source evidence','Check support and abstain when needed'],q('Does retrieving a document guarantee a grounded answer?',['Yes','No; the answer must still be checked against the evidence','Only when the document is long'],1,'Retrieval relevance and answer faithfulness are different failure modes.')],
    ['cloud-reliability','Use deadlines & retry budgets','Retries can help transient failures, but unlimited retries can multiply load and delay recovery.',['Classify the failure','Apply a bounded retry policy','Respect the overall deadline'],q('What should a retry budget count?',['The total permitted attempts, according to a clear contract','Only successful attempts','An unlimited number of failures'],0,'Define whether the first call is included and ensure the total operation respects its deadline.')],
    ['cloud-access','Grant only the access required','A workload should get only the permissions it needs, with a clear identity and auditable access.',['Identify the workload','Grant narrowly scoped permissions','Review and revoke access'],q('What is the least-privilege default?',['Grant the minimum permissions required','Give every service administrator access','Reuse a developer’s personal credentials'],0,'A narrow workload identity reduces unnecessary access and makes ownership clearer.')],
    ['data-replay','Replay events without duplicating effects','A replay is useful only when event identity, processing rules and recovery behaviour are explicit.',['Identify events and checkpoints','Process with a replay policy','Reconcile the recovered output'],q('What risk does a replay create without idempotency?',['The same business effect may be applied again','All data automatically becomes sorted','Every late event disappears'],0,'Reprocessing and repeating the business effect are different concerns. Stable identity helps separate them.')],
    ['data-quality','Make data contracts explicit','Agree on the shape and meaning of a record, then verify both validity and completeness.',['Define the contract','Check records and completeness','Report actionable failures'],q('Does a valid schema prove a batch is complete?',['Yes','No; completeness needs its own checks','Only if every field is a string'],1,'Records can all be well formed while some expected records are missing.')],
    ['intro-concept','Build a relevant introduction','Connect your current strengths, a real contribution and the role you want.',['Where you are now','What you contributed','Why this role fits'],q('What belongs in a strong introduction?',['Relevant strengths and truthful evidence','Every detail of your career','A memorised story unrelated to the role'],0,'Select the information that helps the interviewer understand your fit and contribution.')],
    ['coding-concept','Turn a prompt into verified behaviour','Clarify the task, implement the simplest suitable approach and test its boundaries.',['Clarify the contract','Implement a suitable approach','Test and explain the result'],q('When should boundary cases be considered?',['While clarifying and verifying the solution','Only after the interview ends','Only if the normal case fails'],0,'Boundary cases help expose assumptions before and after implementation.')],
    ['technical-concept','Explain a technical decision','State the constraints, compare reasonable options and explain the evidence behind your choice.',['State the constraints','Compare the options','Justify the decision'],q('What makes a technical recommendation useful?',['An explanation tied to constraints and trade-offs','Claiming one tool is always best','Listing product names without reasoning'],0,'A good choice depends on workload, reliability, cost, ownership and the evidence available.')],
    ['manager-concept','Communicate a decision to stakeholders','Make the decision, risk and evidence clear enough for stakeholders to act.',['Explain the situation','Present evidence and options','Recommend an action and owner'],q('What should accompany a release recommendation?',['Risk, evidence and a clear next action','Only the number of tests','A guarantee that nothing can fail'],0,'Stakeholders need a concrete decision with its assumptions, trade-offs and follow-up ownership.')],
    ['hr-concept','Prepare for mutual fit','Use truthful examples to discuss motivation, working preferences and development.',['Explain your motivation','Use a real example','Ask useful questions'],q('How should you discuss a development area?',['Use a real example and what you are doing about it','Invent an experience','Avoid every limitation'],0,'Specific reflection and action provide more useful evidence than a rehearsed claim of perfection.')]
  ];
  for(const [id,title,lead,steps,question] of general)add(id,title,lead,[['The idea',lead],['Use it when','An interview asks you to explain a decision, workflow or failure mode in this area.'],['Make it concrete','Connect the method to the scenario, then explain the assumptions and limitations.']],steps,[question]);

  const domainCards={
    'shared-structured-answers':[['Context','Give just enough background to make the problem understandable.'],['Contribution','Explain what you did and why you made that choice.'],['Evidence','Use a real outcome, limitation or lesson rather than an invented metric.']],
    'shared-problem-solving':[['Contract','Agree on the inputs, output and boundary rules.'],['Approach','Choose the simplest structure that meets those rules.'],['Verification','Trace a small case, test boundaries and explain the result.']],
    'core-ledger':[['Movements','Entries explain changes that a balance alone cannot show.'],['Atomicity','Related postings must be saved together or not at all.'],['History','Correct a posted mistake with an appropriate linked reversal.']],
    'core-idempotency':[['Stable key','Use the same request identity for a consistent retry.'],['One effect','Return the accepted result without applying the payment again.'],['Conflict','Define what happens when the same key has a different payload.']],
    'ecommerce-inventory':[['Availability','A stock read is a snapshot, not a reservation.'],['Coordination','Reserve atomically so concurrent buyers cannot claim the same unit.'],['Release','Define when an abandoned or failed reservation becomes available again.']],
    'ecommerce-checkout':[['State','Know whether an order is created, paid, fulfilled or cancelled.'],['Transition','Specify which changes are valid and what triggers them.'],['Recovery','Handle duplicate callbacks and partial failures deliberately.']],
    'ai-evaluation':[['Cases','Include representative and difficult examples.'],['Rubric','Define what a good result means before comparing models.'],['Evidence','Inspect failure categories and uncertainty as well as a headline score.']],
    'ai-rag':[['Retrieval','Find context relevant to the user’s question.'],['Grounding','Check that the answer is supported by the retrieved evidence.'],['Abstention','Define an appropriate response when the evidence is insufficient.']],
    'cloud-reliability':[['Deadline','Bound the overall operation, not just each individual call.'],['Retries','Retry appropriate transient failures within a budget.'],['Load','Consider backoff, jitter and the extra work retries create.']],
    'cloud-access':[['Identity','Give the workload an identifiable service identity.'],['Scope','Grant only the permissions required by its work.'],['Audit','Make access changes, review and revocation traceable.']],
    'data-replay':[['Identity','Distinguish an event from a retry or replay of that event.'],['Checkpoint','Know where processing can safely resume.'],['Verification','Reconcile recovered output instead of assuming replay succeeded.']],
    'data-quality':[['Shape','Validate fields, types and required values.'],['Meaning','Check business rules as well as the schema.'],['Completeness','Verify expected records and totals independently.']],
    'intro-concept':[['Now','Describe your current role and relevant strengths.'],['Evidence','Choose one real contribution that connects to this opportunity.'],['Direction','Explain why the role is a useful next step.']],
    'coding-concept':[['Clarify','Turn ambiguous wording into a testable contract.'],['Implement','Choose a suitable data structure and explain the approach.'],['Verify','Test normal and boundary cases before discussing optimisation.']],
    'technical-concept':[['Constraints','State the workload, requirements and limits.'],['Options','Compare credible alternatives and their trade-offs.'],['Decision','Recommend an option and explain the supporting evidence.']],
    'manager-concept':[['Decision','Make the choice or recommendation clear.'],['Risk','Explain impact, likelihood and uncertainty.'],['Action','Name the next step, owner and evidence needed.']],
    'hr-concept':[['Motivation','Connect your interest to the work and team.'],['Reflection','Use honest examples of strengths and development.'],['Mutual fit','Ask questions that help both sides assess the opportunity.']]
  };
  for(const [id,cards] of Object.entries(domainCards))profiles[id].cards=cards;

  const overrides={python:{}};
  const ids=Object.keys(profiles).filter(id=>id.startsWith('1-'));
  const notes={
    python:[
      ['Objects, constructors & immutable state','Initialise each object’s state and decide which values may change. A frozen dataclass does not deeply freeze nested objects.','__init__ receives the instance as self.','A tuple protects its sequence structure, not every nested value.',q('What does @dataclass(frozen=True) primarily prevent?',['Ordinary field assignment','Every change inside nested objects','Every possible use of reflection'],0,'Frozen dataclasses block ordinary attribute assignment. Nested mutable objects still need a copying or immutability policy.')],
      ['Equality, missing values & hashing','Distinguish object identity from value equality, then handle None and blank text deliberately.','is compares identity; == uses value equality.','Objects used as dictionary keys need a consistent equality/hash contract.',q('Which operator checks Python object identity?',['is','==','in'],0,'is checks whether two references identify the same object. == invokes value comparison.')],
      ['Decimal money & rounding','Construct Decimal from decimal text and choose an explicit rounding rule.','Decimal operations produce values; keep the returned result.','Use quantize with an agreed precision and rounding mode.',q('Which input preserves the intended decimal 0.1?',['Decimal("0.1")','Decimal(0.1)','float("0.1")'],0,'A decimal string avoids importing the binary floating-point approximation into Decimal.')],
      ['Collections, order & copies','Choose a list, set, dictionary or queue from the ordering and membership contract.','A set keeps distinct members; it is not an ordered list.','A shallow copy retains references to nested mutable objects.',q('Does list(existing) deeply copy nested mutable objects?',['Yes','No','Only for dictionaries'],1,'The outer list is copied; nested object references are retained.')],
      ['Dictionaries & default values','A dictionary connects keys to values. Read an existing value or supply a missing-key default.','d.get(key, default) does not insert the key.','A present key mapped to None does not use the missing-key default.',q('What is {"X": None}.get("X", 0)?',['None','0','KeyError'],0,'X is present, so its stored None value is returned.')],
      ['Comprehensions & lazy pipelines','Choose between an eagerly built collection and a lazy iterator, then make the reduction explicit.','List comprehensions build lists eagerly.','Generator expressions are lazy and can be consumed.',q('Which expression is lazy?',['[x * 2 for x in values]','(x * 2 for x in values)','list(values)'],1,'A generator expression produces values as it is consumed instead of building a list immediately.')],
      ['Grouping & exact reductions','Choose the group key, then accumulate each group’s result using the right numeric type.','Dictionaries or defaultdict can collect records by key.','Keep Decimal arithmetic exact until the agreed rounding point.',q('What determines a record’s group?',['The chosen grouping key','Its position in memory','The length of its printed representation'],0,'The grouping rule should match the required business classification.')],
      ['Tasks, futures & executor cleanup','Choose threads, processes or asynchronous work according to the workload and runtime.','A Future represents an eventual result or failure.','Own the executor lifecycle and make timeout behaviour explicit.',q('Does future.result() always return immediately?',['Yes','No; it can wait for completion','Only for integer results'],1,'Obtaining a result may block. Define an appropriate waiting and timeout policy.')],
      ['Coordinate shared state','Protect the complete shared update, rather than assuming several separate operations form one atomic action.','A lock can coordinate a read-modify-write critical section.','Queue capacity and overload policy remain separate design decisions.',q('What should a lock protect for a shared counter?',['The whole read-modify-write operation','Only printing the result','Only creation of the counter'],0,'Coordination must cover the operation whose consistency you need.')],
      ['Thread context & async context','Match context storage to the execution model and clean it up at the boundary you own.','threading.local is associated with a thread.','ContextVar supports context-aware asynchronous code; propagation rules still matter.',q('Does threading.local automatically make a value request-scoped?',['Yes','No; a reused thread can outlive a request','Only for strings'],1,'Thread lifetime and request lifetime differ. Cleanup and propagation need explicit policies.')]
    ]
  };
  notes.python.forEach(([title,lead,a,b,question],n)=>overrides.python[ids[n]]={title,lead,cards:[['The idea',lead],['Use the native model',a],['Watch out',b]],quiz:[question]});
  return {profiles,overrides};
})();
